<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{Category,Feature,Location}; use App\Services\AdminAudit; use Illuminate\Http\Request; use Illuminate\Support\Str;
class TaxonomyController extends Controller { private array $models=['categories'=>Category::class,'features'=>Feature::class,'locations'=>Location::class]; public function index(string $type){$m=$this->model($type);return view('admin.taxonomies.index',['type'=>$type,'items'=>$m::withCount('restaurants')->orderBy('name')->paginate(50)]);}public function store(Request $r,string $type,AdminAudit $audit){$m=$this->model($type);$d=$r->validate(['name'=>'required|string|max:255','slug'=>'nullable|alpha_dash|max:255','parent_id'=>$type==='locations'?'nullable|exists:locations,id':'prohibited']);$d['slug']=$d['slug']?:Str::slug($d['name']);$d['legacy_term_id']=random_int(1_000_000_000,2_000_000_000);$item=$m::create($d);$audit->record($type.'.created',$item);return back()->with('status','Élément créé.');}public function update(Request $r,string $type,int $id,AdminAudit $audit){$m=$this->model($type);$item=$m::findOrFail($id);$d=$r->validate(['name'=>'required|string|max:255','slug'=>'required|alpha_dash|max:255','parent_id'=>$type==='locations'?'nullable|exists:locations,id':'prohibited']);abort_if($type==='locations'&&$item->id==($d['parent_id']??null),422);$item->update($d);$audit->record($type.'.updated',$item,$d);return back()->with('status','Élément enregistré.');}public function destroy(string $type,int $id,AdminAudit $audit){$m=$this->model($type);$item=$m::findOrFail($id);abort_if($item->restaurants()->exists(),422,'Des restaurants y sont encore associés.');$audit->record($type.'.deleted',$item);$item->delete();return back()->with('status','Élément supprimé.');}private function model(string $type):string{abort_unless(isset($this->models[$type]),404);return $this->models[$type];}}
